mapper.update:
UPDATE appointment
SET status = #{status}

    , completed_at = NOW()


    , cancelled_at = NOW()

WHERE appointment_id = #{appointmentId}

mapper.select:
SELECT a.*, p.real_name
FROM appointment a
         LEFT JOIN patient p ON a.patient_id = p.patient_id
WHERE a.doctor_id = #{doctorId}
  AND a.patient_id = #{patientId}
ORDER BY a.created_at DESC
